import {AGES,EVENTS,STAT_INFO,PEOPLE,createGame,currentEvent,choose,advance,interpolate,matches,getEnding,validateSave,diaryText} from './engine.mjs?v=1';
const KEY='ikutsumono-ashita-v1',PREF='ikutsumono-ashita-hints';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${{leaf:'<path d="M6 21V10C6 3 15 2 20 3c1 9-5 14-13 11M6 21c3-6 9-6 13-3M7 14l7-6"/>',book:'<path d="M12 5c-3-2-6-2-9-1v16c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v16"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--paper)"/><circle cx="16" cy="17" r="3" fill="var(--paper)"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',save:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0z"/><circle cx="12" cy="10" r="2"/>'}[name]||''}</svg>`;
let state=null,started=false,trait='curious',hints=true,modal=null,saveError=false,focusReturn=null;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validateSave(parsed))state=parsed;else saveError=true;}hints=localStorage.getItem(PREF)!=='false';}catch{saveError=true;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));saveError=false;}catch{saveError=true;toast('自動保存ができませんでした。設定からセーブを書き出せます。');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function t(text){return esc(interpolate(text,state));}
function chapter(age){return age<20?'芽吹きの季節':age<30?'世界が広がる頃':age<40?'自分の道を探して':age<50?'暮らしの真ん中で':age<65?'もう一度、あたらしく':'実りと、その先へ';}
function header(){return `<header class="site-header"><a class="brand" href="#" data-action="home" aria-label="タイトル画面へ"><span class="brand-mark">${icon('leaf',28)}</span><span>いくつもの明日<small>A LIFE OF YOUR OWN</small></span></a><nav aria-label="ゲームメニュー"><button class="nav-btn" aria-label="人生のしおり" data-action="journal" ${!state?'disabled':''}>${icon('book')}<span>人生のしおり</span></button><button class="nav-btn" aria-label="登場人物" data-action="people" ${!state?'disabled':''}>${icon('people')}<span>登場人物</span></button><button class="icon-btn" data-action="settings" aria-label="設定">${icon('settings')}</button></nav></header>`;}
function intro(){return `<main class="intro"><div class="intro-art" role="img" aria-label="海と山に囲まれた、穏やかな日本の街並み"></div><div class="intro-copy"><p class="eyebrow"><span></span> あなたが選ぶ、ひとつの人生。</p><h1>まだ知らない、<br>あなたに<span class="accent">会いに。</span></h1><p class="intro-lead">あの日、違う道を選んでいたら。<br>そんな「もしも」を、ここから始めよう。</p><p class="intro-description">16歳の春。小さな街に暮らす、ひとりの主人公。<br>夢も、仕事も、誰と過ごすかも。<br>ひとつずつ選んで、あなただけの物語を。</p>${state?`<div class="resume-card"><div><small>あなたの物語が待っています</small><strong>${esc(state.name)} <span>・ ${AGES[state.index]}歳${state.phase==='ending'?' / 完結':''}</span></strong></div><button class="primary" data-action="resume">${state.phase==='ending'?'人生を振り返る':'つづきから'} ${icon('arrow')}</button></div><button class="text-btn new-link" data-action="new">新しい人生をはじめる ${icon('arrow',16)}</button>`:setupForm()}<p class="intro-foot">32の節目 <span>·</span> 何度でも、新しい人生 <span>·</span> 自動保存</p></div><div class="art-caption"><span>PROLOGUE</span><p>どんな道も、あなたの物語になる。</p></div></main><footer class="intro-footer"><span>正解のない選択に、あなたらしさがある。</span><span>物語を味わう、人生シミュレーション</span></footer>`;}
function setupForm(){return `<form id="start-form"><div class="name-row"><label for="player-name">主人公の名前</label><input id="player-name" name="name" type="text" maxlength="16" placeholder="凪" value="凪" autocomplete="off" required></div><fieldset class="traits"><legend>はじまりの性格 <span>この先の選択で、変わっていきます。</span></legend><div class="trait-options">${[['thoughtful','思慮深い','知性'],['curious','好奇心旺盛','勇気'],['warm','人が好き','つながり']].map(([id,label,stat])=>`<button type="button" data-trait="${id}" class="trait ${trait===id?'selected':''}" aria-pressed="${trait===id}">${label}<small>${stat} ＋15</small></button>`).join('')}</div></fieldset><button type="submit" class="primary start-button">物語をはじめる ${icon('arrow')}</button></form>`;}
function statBars(){return Object.entries(STAT_INFO).map(([key,info])=>`<div class="stat-row"><div><span>${info.label}</span><b>${state.stats[key]}</b></div><div class="stat-track"><i style="width:${state.stats[key]}%;background:${info.color}"></i></div></div>`).join('');}
function sidebar(){return `<aside class="sidebar"><div class="profile-heading"><div class="avatar">${icon('leaf',31)}</div><div><span class="micro">いまのあなた</span><h2>${esc(state.name)}<span>${AGES[state.index]}歳</span></h2></div></div><div class="profile-meta"><div><span>仕事・学び</span><strong>${esc(state.career)}</strong></div><div><span>暮らす場所</span><strong>${esc(state.home)}</strong></div><div><span>パートナー</span><strong>${esc(state.relationship)}</strong></div></div><div class="stats">${statBars()}</div><div class="money"><span>手元のお金</span><b>${state.money.toLocaleString('ja-JP')}<small>万円</small></b></div><p class="money-note">選択による収支の記録</p><div class="sidebar-memory"><div class="section-label"><span>最近の足あと</span>${icon('book',16)}</div>${state.history.length?state.history.slice(-3).reverse().map(h=>`<div class="small-memory"><span>${h.age}歳</span><p>${esc(h.choice)}</p></div>`).join(''):'<p class="empty-memory">最初の一歩は、ここから。</p>'}<button class="text-btn" data-action="journal">すべての足あとを見る ${icon('arrow',15)}</button></div><p class="side-quote">「選ばなかった道も、<br>あなたの一部になる。」</p></aside>`;}
function chips(effects={}){return Object.entries(effects).filter(([,v])=>v).map(([k,v])=>`<span class="effect ${v<0?'minus':''}">${k==='money'?'お金':STAT_INFO[k]?.label||k} ${v>0?'＋':'−'}${Math.abs(v)}${k==='money'?'万':''}</span>`).join('');}
function lockReason(c){const r=c.requires||{};const parts=[];if(r.money!==undefined&&state.money<r.money)parts.push(`所持金${r.money}万円`);for(const [k,v] of Object.entries(r.stats||{}))if(state.stats[k]<v)parts.push(`${STAT_INFO[k]?.label||k}${v}`);if(r.flags?.some(f=>!state.flags.includes(f))||r.notFlags?.some(f=>state.flags.includes(f)))parts.push('これまでの選択');return parts.join('・')+'が条件';}
function game(){const e=currentEvent(state),result=state.phase==='result',h=state.history.at(-1);return `<main class="game-layout"><section class="story-column"><div class="chapter-line"><span>CHAPTER ${String(state.index+1).padStart(2,'0')} <i>/ ${AGES.length}</i></span><span>${chapter(e.age)}</span></div><article class="story-card"><div class="scene scene-${e.scene||'town'}"><img src="./assets/town.svg" alt="穏やかな街と、その向こうに続く風景"><div class="scene-overlay"></div><div class="scene-label"><span>${esc(e.category)}</span><div class="scene-age">${e.age}<small>歳</small></div><p>${t(e.lead)}</p></div><span class="scene-location">${icon('pin',14)} ${esc(state.home)}</span></div><div class="story-content"><div class="story-title-row"><span class="chapter-marker">${String(state.index+1).padStart(2,'0')}</span><h1 id="story-heading" tabindex="-1">${t(e.title)}</h1></div><div class="prose">${interpolate(e.text,state).split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div>${result?`<div class="result-panel" role="status"><p class="eyebrow">${icon('check',15)} あなたが選んだこと</p><h3>${esc(h.choice)}</h3><p>${esc(h.result)}</p><div class="effects">${chips(h.deltas)}</div></div><div class="next-row"><span>${state.index===AGES.length-1?'あなたの足あとを、一冊の物語に。':'この選択も、あなたの一部になる。'}</span><button class="primary" data-action="next">${state.index===AGES.length-1?'人生を振り返る':'次の季節へ'} ${icon('arrow')}</button></div>`:`<div class="choice-intro"><span>あなたなら、どうする？</span><label><input type="checkbox" id="hint-toggle" ${hints?'checked':''}>影響のヒント</label></div><div class="choices">${e.choices.map((c,i)=>{const enabled=matches(state,c.requires);return `<button class="choice ${enabled?'':'locked'}" data-choice="${esc(c.id)}" ${enabled?'':'disabled'}><span class="choice-index">${String(i+1).padStart(2,'0')}</span><span class="choice-copy"><strong>${t(c.title)}</strong><span class="choice-desc">${t(c.desc)}</span>${!enabled?`<span class="lock-hint">${esc(lockReason(c))}</span>`:hints?`<span class="effects">${chips(c.effects)}</span>`:''}</span><span class="choice-arrow">↗</span></button>`;}).join('')}</div><p class="keyboard-hint">ひとつ選ぶと、物語が進みます。<span>キー 1–4 でも選べます</span></p>`}</div></article><div class="life-progress"><div class="life-track"><i style="width:${(state.index+ (result?1:0))/AGES.length*100}%"></i></div><div>${[16,25,40,60,80].map(a=>`<span class="${e.age>=a?'passed':''}">${a}歳</span>`).join('')}</div></div><div class="save-status">${saveError?'自動保存できません。設定から書き出してください。':`${icon('check',12)} このブラウザに自動保存されます`}</div></section>${sidebar()}</main>`;}
function ending(){const end=getEnding(state);const closePeople=Object.entries(state.bonds).sort((a,b)=>b[1]-a[1])[0];return `<main class="ending"><div class="ending-art"></div><div class="ending-content"><span class="eyebrow">THE STORY OF ${esc(state.name)}</span><h1>${esc(end.title)}</h1><p class="ending-prose">${esc(end.text)}</p><div class="end-summary"><span>16歳から80歳</span><i></i><span>${state.history.length}の選択</span><i></i><span>${esc(state.career)}</span></div><div class="ending-cards"><div><small>大切にしてきたもの</small><strong>${STAT_INFO[end.top].label}</strong><p>日々の選択が、あなたらしさに。</p></div><div><small>そばに残るつながり</small><strong>${closePeople[1]>20?PEOPLE[closePeople[0]].name:'あなた自身'}</strong><p>${closePeople[1]>20?'ともに過ごした時間が、今もここに。':'ひとりの時間も、大切な物語。'}</p></div><div><small>たどり着いた暮らし</small><strong>${esc(state.home)}</strong><p>${esc(state.relationship)}</p></div></div><blockquote>人生は、点数ではない。<br>あなたが選んだ日々の、重なりだ。</blockquote><div class="end-actions"><button class="primary" data-action="journal">${icon('book')} 人生のしおりを開く</button><button class="secondary" data-action="download-diary">${icon('save')} 物語を残す</button></div><button class="text-btn new-link" data-action="new">もうひとつの人生を歩む ${icon('arrow',17)}</button><p class="end-foot">この先にも、きっと明日はつづく。</p></div></main>`;}
function render(focus=false){$('#app').innerHTML=header()+(started&&state?(state.phase==='ending'?ending():game()):intro());if(focus){window.scrollTo({top:0,behavior:'instant'});$('#story-heading')?.focus({preventScroll:true});}}
function openModal(type){focusReturn=document.activeElement;modal=type;renderModal();$('#game-dialog').showModal();$('#game-dialog .close-modal')?.focus();}
function closeModal(){const dialog=$('#game-dialog');dialog?.close();$('#modal-root').innerHTML='';modal=null;if(focusReturn?.isConnected)focusReturn.focus();else $('[data-action="settings"]')?.focus();}
function renderModal(){let title='',content='';if(modal==='journal'){title='人生のしおり';content=`<p class="modal-sub">${esc(state.name)}が選んできた、小さなこと、大きなこと。</p>${state.history.length?`<div class="journal">${state.history.map(h=>`<article><div class="journal-age">${h.age}<small>歳</small></div><div><h3>${esc(h.title)}</h3><strong>${esc(h.choice)}</strong><p>${esc(h.result)}</p></div></article>`).join('')}</div><button class="secondary full-width" data-action="download-diary">${icon('save')} ここまでの物語を保存</button>`:'<div class="empty-state">まだ白い、最初のページ。<br>ひとつ選ぶと、ここに足あとが残ります。</div>'}`;}
 if(modal==='people'){title='あなたをとりまく人たち';content=`<p class="modal-sub">近づいたり、少し離れたり。それぞれの人生が、交わる。</p><div class="people-list">${Object.entries(PEOPLE).map(([id,p])=>{const v=state.bonds[id];return `<article><div class="person-avatar" style="background:${p.color}">${p.initial}</div><div><h3>${p.name}<small>${p.role}</small></h3><p>${v>=65?'心を許せる、大切な存在。':v>=35?'日々を分かち合う、身近な存在。':v>0?'これから、少しずつ知っていく。':'まだ、物語の途中で出会う前。'}</p><div class="bond-track" aria-label="親しさ ${v}/100"><i style="width:${v}%"></i></div></div></article>`;}).join('')}</div><p class="subtle">親しさは、それぞれの人との選択で変わります。</p>`;}
 if(modal==='settings'){title='物語の設定';content=`<div class="settings-row"><div><strong>選択のヒント</strong><p>選ぶ前に、能力やお金への影響を表示します。</p></div><input aria-label="選択のヒントを表示" type="checkbox" id="settings-hints" ${hints?'checked':''}></div><div class="setting-section"><h3>セーブデータ</h3><p>このブラウザに自動保存します。別の端末で続けたいときは、セーブデータを移せます。</p><div class="button-pair"><button class="secondary" data-action="export" ${!state?'disabled':''}>${icon('save',17)} 書き出す</button><button class="secondary" data-action="import">読み込む</button><input type="file" id="save-file" accept=".json,application/json" hidden></div></div><div class="setting-section"><h3>このゲームについて</h3><p>現代の日本を舞台にしたフィクションです。32の節目と、選択によって変わる${EVENTS.length}の場面を用意しています。お金は選択による収支のみを記録します。自動的な給与・生活費の計算はありません。</p><p>すべての人生に、異なるよさがあります。能力の数字は、勝敗を決める点数ではありません。</p></div>${state?'<button class="text-btn danger" data-action="new">新しい人生をはじめる</button>':''}`;}
 if(modal==='new'){title='もうひとつの、はじまり。';content=`<p class="modal-sub">新しく始めると、このブラウザの進行を置き換えます。今の人生を残したい場合は、先にセーブを書き出してください。</p><button class="secondary full-width" data-action="export">${icon('save')} 今のセーブを書き出す</button><div class="modal-setup">${setupForm()}</div>`;}
 $('#modal-root').innerHTML=`<dialog id="game-dialog" class="modal" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn close-modal" data-action="close" aria-label="閉じる">${icon('close')}</button></div><div class="modal-body">${content}</div></dialog>`;
 $('#game-dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal();});$('#game-dialog').addEventListener('click',e=>{if(e.target===$('#game-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setHints(value){hints=value;try{localStorage.setItem(PREF,String(value));}catch{}if(started)render();}
document.addEventListener('submit',e=>{if(e.target.id!=='start-form')return;e.preventDefault();const name=new FormData(e.target).get('name');state=createGame(String(name),trait);started=true;closeModal();persist();render(true);});
document.addEventListener('click',e=>{
 const tr=e.target.closest('[data-trait]');if(tr){trait=tr.dataset.trait;document.querySelectorAll('[data-trait]').forEach(el=>{el.classList.toggle('selected',el.dataset.trait===trait);el.setAttribute('aria-pressed',String(el.dataset.trait===trait));});return;}
 const ch=e.target.closest('[data-choice]');if(ch&&!ch.disabled&&state?.phase==='choice'){state=choose(state,ch.dataset.choice);persist();render();$('.result-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});$('.next-row button')?.focus({preventScroll:true});return;}
 const a=e.target.closest('[data-action]');if(!a||a.disabled)return;e.preventDefault();switch(a.dataset.action){
 case 'home':started=false;render();window.scrollTo(0,0);break;
 case 'resume':started=true;render(true);break;
 case 'journal':case 'people':case 'settings':openModal(a.dataset.action);break;
 case 'new':openModal('new');break;
 case 'close':closeModal();break;
 case 'next':state=advance(state);persist();render(true);break;
 case 'download-diary':download(diaryText(state),`${state.name}の人生.txt`,'text/plain;charset=utf-8');toast('人生の物語を書き出しました');break;
 case 'export':download(JSON.stringify(state,null,2),'ikutsumono-ashita-save.json','application/json');toast('セーブデータを書き出しました');break;
 case 'import':$('#save-file').click();break;
 }});
document.addEventListener('change',async e=>{if(e.target.id==='hint-toggle'||e.target.id==='settings-hints')setHints(e.target.checked);if(e.target.id==='save-file'){const file=e.target.files[0];if(!file)return;if(file.size>250000){toast('ファイルが大きすぎます。ゲームのセーブを選んでください。');return;}try{const s=JSON.parse(await file.text());if(!validateSave(s))throw new Error('invalid');if(state&&!window.confirm('読み込んだセーブで、現在の進行を置き換えますか？'))return;state=s;started=true;persist();closeModal();render(true);toast('セーブデータを読み込みました');}catch{toast('このセーブデータは読み込めません。ファイルを確認してください。');}}});
document.addEventListener('keydown',e=>{if(modal||!started||!state||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName))return;if(state.phase==='choice'&&['1','2','3','4'].includes(e.key)){const btn=document.querySelectorAll('[data-choice]')[Number(e.key)-1];if(btn&&!btn.disabled)btn.click();}else if(e.key==='Enter'&&state.phase==='result')$('[data-action="next"]')?.click();});
render();if(saveError)toast('保存データを読み込めませんでした。新しい人生を始められます。');
